\title{A Rigorous Anatomy of the Curie--Weiss Phase Transition}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We give a complete and self-contained analysis of the second-order phase
transition in the mean-field (Curie--Weiss) model of a system of coupled binary
degrees of freedom. The model is governed by the scalar self-consistency
equation $m = \tanh(\beta m)$, where $m$ is the order parameter (average
alignment) and $\beta > 0$ is the coupling (inverse temperature). Our central
result locates the critical point exactly: a nontrivial positive order
parameter exists if and only if $\beta > 1$. Below the threshold the disordered
state $m=0$ is the unique nonnegative solution; above it a positive solution
appears, is unique, and is born continuously from zero---the hallmark of a
second-order transition. We further show that every solution satisfies
$|m|<1$, that solutions occur in symmetric $\pm m$ pairs, and that the
introduction of any positive external field $h>0$ destroys the sharp dichotomy:
the field-driven equation $m = \tanh(\beta m + h)$ possesses a positive solution
in $(0,1)$ for \emph{every} coupling $\beta$. The analytic engine consists of two
sharp elementary inequalities for the hyperbolic tangent, $\tanh y < y$ and
$y - y^3/3 < \tanh y$ for $y>0$, each established by monotonicity of an
auxiliary function through its derivative.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{phase transition} is a qualitative change in the macroscopic state of a
system produced by the smooth variation of a control parameter. The paradigm is
ferromagnetism: a magnetic material is disordered (no net magnetization) above
a critical temperature and spontaneously ordered below it. The quantity that
distinguishes the two regimes---the magnetization---is the \emph{order
parameter}, and the value of the control parameter at which its qualitative
behavior changes is the \emph{critical point}.

Mean-field theory replaces the detailed interactions among microscopic degrees
of freedom by a single average field to which each degree of freedom responds.
For a system of $\pm 1$ spins with all-to-all coupling of strength $\beta$
(inverse temperature), this reduction yields the \textbf{Curie--Weiss
self-consistency equation}
\begin{equation}
  m = \tanh(\beta m), \label{eq:cw}
\end{equation}
in which the order parameter $m \in [-1,1]$ is a fixed point of
$m \mapsto \tanh(\beta m)$. Equation~\eqref{eq:cw} is the simplest nontrivial
model exhibiting a genuine phase transition.

This paper provides a rigorous account of the structure of~\eqref{eq:cw} and of
its field-driven generalization
\begin{equation}
  m = \tanh(\beta m + h). \label{eq:cwh}
\end{equation}
Our contributions are: (i) a sharp existence/nonexistence dichotomy locating the
critical coupling at $\beta_c = 1$; (ii) uniqueness of the positive branch;
(iii) qualitative properties (boundedness, symmetry, continuity of onset)
identifying the transition as second-order; and (iv) a proof that any positive
external field removes the sharp transition.

\section{Two sharp inequalities for $\tanh$}

Throughout, $\tanh y = \sinh y / \cosh y$, with $\cosh y > 0$ for all real $y$,
so $\tanh$ is smooth with derivative
\begin{equation}
  \frac{d}{dy}\tanh y = \frac{1}{\cosh^2 y} = 1 - \tanh^2 y, \label{eq:dtanh}
\end{equation}
which lies in $(0,1]$ and equals $1$ only at $y=0$. Hence $\tanh$ is strictly
increasing with maximal slope $1$ at the origin, and $-1 < \tanh y < 1$.

\begin{lemma}[Strict sublinearity]\label{lem:sublinear}
For every $y>0$, $\tanh y < y$.
\end{lemma}
\begin{proof}
Let $F(y) = y - \tanh y$. By~\eqref{eq:dtanh},
$F'(y) = 1 - 1/\cosh^2 y = \tanh^2 y > 0$ for $y>0$. Since $F(0)=0$, the mean
value theorem yields $c\in(0,y)$ with $F(y) = F'(c)\,y > 0$, so $\tanh y < y$.
\end{proof}

\begin{lemma}[Sharp cubic lower bound]\label{lem:cubic}
For every $y>0$, $\displaystyle y - \frac{y^3}{3} < \tanh y$.
\end{lemma}
\begin{proof}
Let $G(y) = \tanh y - y + y^3/3$. By~\eqref{eq:dtanh},
$G'(y) = 1/\cosh^2 y - 1 + y^2 = y^2 - \tanh^2 y$. For $y>0$,
Lemma~\ref{lem:sublinear} gives $0 < \tanh y < y$, so $\tanh^2 y < y^2$ and
$G'(y) > 0$. Since $G(0)=0$, the mean value theorem gives $G(y) > 0$.
\end{proof}

Together the lemmas bracket $\tanh$ near the origin:
\begin{equation}
  y - \frac{y^3}{3} < \tanh y < y, \qquad y > 0. \label{eq:bracket}
\end{equation}

\section{General properties of solutions}

\begin{proposition}[Boundedness]\label{prop:bdd}
If $m = \tanh(\beta m)$, then $|m| < 1$.
\end{proposition}
\begin{proof}
Immediate from $-1 < \tanh(x) < 1$ for all real $x$, since $m = \tanh(\beta m)$.
\end{proof}

\begin{proposition}[Symmetry]\label{prop:symm}
If $m$ solves~\eqref{eq:cw}, so does $-m$.
\end{proposition}
\begin{proof}
$\tanh$ is odd, so $\tanh(\beta(-m)) = -\tanh(\beta m) = -m$.
\end{proof}

\section{The subcritical (disordered) phase}

\begin{theorem}[No spontaneous order for $\beta \le 1$]\label{thm:sub}
If $\beta \le 1$, $m \ge 0$, and $m = \tanh(\beta m)$, then $m = 0$.
\end{theorem}
\begin{proof}
Suppose $m > 0$. If $\beta m \le 0$ then $\tanh(\beta m) \le 0 < m$, contra\-dicting
\eqref{eq:cw}. Hence $\beta m > 0$, and Lemma~\ref{lem:sublinear} gives
$\tanh(\beta m) < \beta m \le m$ (using $\beta \le 1$, $m>0$). Then
$m = \tanh(\beta m) < m$, a contradiction. Thus $m=0$.
\end{proof}

\section{The supercritical (ordered) phase}

\begin{theorem}[Emergence of order for $\beta > 1$]\label{thm:super}
If $\beta > 1$, there exists $m > 0$ with $m = \tanh(\beta m)$.
\end{theorem}
\begin{proof}
Let $f(m) = \tanh(\beta m) - m$, continuous on $[0,1]$. Put
$c = \sqrt{3(\beta-1)/\beta^3}$ and $m_0 = \tfrac12\min(1,c)$, so $0<m_0<1$ and
$\beta^3 m_0^2/3 < \beta-1$. Since $\beta m_0 > 0$, Lemma~\ref{lem:cubic} gives
\[
  \tanh(\beta m_0) > \beta m_0 - \frac{\beta^3 m_0^3}{3}
  > \beta m_0 - (\beta-1)m_0 = m_0,
\]
so $f(m_0) > 0$. Also $f(1) = \tanh(\beta) - 1 < 0$. By the intermediate value
theorem there is $m \in (m_0,1)$ with $f(m) = 0$, i.e. $\tanh(\beta m) = m$ and
$m > 0$.
\end{proof}

Because $m_0 \to 0$ as $\beta \downarrow 1$, the positive branch is born at
zero: the onset is continuous.

\section{The sharp phase transition}

\begin{theorem}[Curie--Weiss phase transition]\label{thm:pt}
For every real $\beta$,
\[
  \bigl(\exists\, m > 0 : m = \tanh(\beta m)\bigr) \iff \beta > 1.
\]
\end{theorem}
\begin{proof}
($\Rightarrow$) If $m>0$ solves~\eqref{eq:cw} but $\beta\le 1$, Theorem~\ref{thm:sub}
forces $m=0$, a contradiction. ($\Leftarrow$) Theorem~\ref{thm:super}.
\end{proof}

The critical coupling is exactly $\beta_c = 1$; since the order parameter tends
to $0$ as $\beta \to 1^+$, the transition is second-order (continuous).

\section{Uniqueness of the ordered state}

\begin{theorem}[Uniqueness of the positive branch]\label{thm:uniq}
If $m_1, m_2 > 0$ both satisfy~\eqref{eq:cw} for the same $\beta$, then $m_1 = m_2$.
\end{theorem}
\begin{proof}
Assume $m_1 < m_2$. Let $g(m) = \tanh(\beta m)$, so $g'(m) = \beta/\cosh^2(\beta m)$.
The mean value theorem on $[m_1,m_2]$ gives $\xi\in(m_1,m_2)$ with
$g'(\xi) = (m_2-m_1)/(m_2-m_1) = 1$, and on $[0,m_1]$ gives $\eta\in(0,m_1)$ with
$g'(\eta) = m_1/m_1 = 1$. But $0<\eta<\xi$ implies
$\cosh(\beta\xi) > \cosh(\beta\eta)$, hence $g'(\xi) < g'(\eta)$, contradicting
$g'(\xi)=g'(\eta)=1$. Therefore $m_1 = m_2$.
\end{proof}

\section{The effect of an external field}

\begin{theorem}[A positive field destroys the sharp transition]\label{thm:field}
For any coupling $\beta$ and any field $h>0$, there exists $m \in (0,1)$ with
$m = \tanh(\beta m + h)$.
\end{theorem}
\begin{proof}
Let $f(m) = \tanh(\beta m + h) - m$, continuous on $[0,1]$. Then
$f(0) = \tanh(h) > 0$ and $f(1) = \tanh(\beta+h) - 1 < 0$. The intermediate value
theorem yields $m \in (0,1)$ with $f(m) = 0$.
\end{proof}

Because this holds for every $\beta$, the sharp dichotomy of
Theorem~\ref{thm:pt} is rounded off by any positive field.

\section{Discussion and future work}

The entire phenomenology reduces to the two inequalities~\eqref{eq:bracket}.
Natural extensions include: (1) proving the quantitative onset
$m_*(\beta) = \sqrt{3(\beta-1)} + o(\sqrt{\beta-1})$ and thereby the mean-field
exponent $1/2$, using a matching cubic upper bound
$\tanh y < y - y^3/3 + 2y^5/15$; (2) uniqueness of the solution
of~\eqref{eq:cwh} for $h \ne 0$; (3) a variational characterization via the free
energy $f(m) = m^2/2 - (1/\beta)\log\cosh(\beta m)$; (4) continuity and strict
monotonicity of the branch $\beta \mapsto m_*(\beta)$ on $(1,\infty)$; and (5) a
percolation analogue on rooted trees, where the branching-process survival
probability is the order parameter and $\mu_c = 1$ the critical point.

