"""Trace the ordered branch m*(beta) and its mirror -m*(beta) across the
critical coupling, exhibiting the pitchfork bifurcation at beta_c = 1."""
from __future__ import annotations
import math
from typing import Optional

def positive_solution(beta: float) -> Optional[float]:
    """Bisection for the positive root of m = tanh(beta*m); None if beta <= 1."""
    f = lambda m: math.tanh(beta * m) - m
    lo, hi = 1e-12, 1.0 - 1e-15
    if f(lo) <= 0.0 or f(hi) >= 0.0:
        return None
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(lo) * f(mid) < 0.0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)

def main() -> None:
    print("Pitchfork bifurcation of m = tanh(beta*m)")
    print(f"{'beta':>6} | {'+m*':>10} | {'-m*':>10}")
    for i in range(26):
        beta = 0.5 + 2.5 * i / 25
        m = positive_solution(beta) or 0.0
        print(f"{beta:>6.2f} | {m:>10.6f} | {-m:>10.6f}")

if __name__ == "__main__":
    main()

"""Illustrate the variational picture: the Curie-Weiss free energy
    f(m) = m^2/2 - (1/beta) log cosh(beta m)
has its global minimizer at m = 0 for beta <= 1 and at the nonzero
self-consistent solution for beta > 1."""
from __future__ import annotations
import math

def free_energy(m: float, beta: float) -> float:
    """Curie-Weiss free energy per spin."""
    return 0.5 * m * m - (1.0 / beta) * math.log(math.cosh(beta * m))

def argmin_free_energy(beta: float, grid: int = 20001) -> float:
    """Global minimizer of f over m in [-1, 1] by dense scan."""
    best_m, best_f = 0.0, float("inf")
    for i in range(grid):
        m = -1.0 + 2.0 * i / (grid - 1)
        f = free_energy(m, beta)
        if f < best_f:
            best_f, best_m = f, m
    return best_m

def main() -> None:
    print("Global minimizer of the Curie-Weiss free energy")
    print(f"{'beta':>6} | {'argmin f':>12}")
    for beta in [0.5, 0.9, 1.0, 1.2, 1.5, 2.0, 3.0]:
        print(f"{beta:>6.2f} | {argmin_free_energy(beta):>12.6f}")
    print("Minimizer is 0 for beta <= 1 and nonzero (symmetry-broken) for beta > 1.")

if __name__ == "__main__":
    main()

